import {loadCompressed} from './korea-data.mjs';
import {setLayerVisible} from './adaptive-lines.mjs';

// A country-supplied, dated reference overlay. Administrative selection stays in
// the shared regional renderer; this controller owns only its sources and cards.
export async function createControlOverview(map,{country,prefix,base,sidebar,fit,onSelect}){
 let [facts,territories,formal]=await Promise.all([fetch(base+'control/facts.json').then(r=>{if(!r.ok)throw Error('Control reference unavailable');return r.json();}),loadCompressed(base+'control/territories.bin'),loadCompressed(base+'control/formal.bin')]);
 const records=[...facts.records,...facts.military.map(r=>({...r,en:r.name,local:'',kind:'Reported military centre',controlActor:true,controlType:'centre',level:1,center:r.center,bounds:[[r.center[0]-.07,r.center[1]-.07],[r.center[0]+.07,r.center[1]+.07]],aliases:[]})),...formal.features.map(f=>{const b=featureBounds(f.geometry);return{id:f.properties.id,en:f.properties.name,local:f.properties.local,kind:'Formal self-administered area',controlActor:true,controlType:'formal',level:1,bounds:b,center:[(b[0][0]+b[1][0])/2,(b[0][1]+b[1][1])/2],aliases:[f.properties.name]};})];
 const byId=new Map(records.map(r=>[r.id,r])),panel=document.createElement('section');panel.className='control-overview';panel.innerHTML=`<label class="control-overview-toggle"><span>Control &amp; administrations</span><input type="checkbox" id="${prefix}-control-overlay" data-nav checked></label><div class="control-overview-content"><p class="control-date">Dated reference · checked 18 October 2026</p><ul class="control-legend"><li><i style="--swatch:#b64a42"></i>Reported military-held urban centres</li><li><i style="--swatch:#7164b5"></i>Wa ceasefire territories · UWSA</li><li><i style="--swatch:#b18a2f"></i>Mongla ceasefire territory · NDAA</li><li><i style="--swatch:#d9dbd6"></i>Control unclassified or mixed</li></ul><p class="control-caveat">Grey does not mean military-controlled. City markers do not assign control to an entire township. Territory boundaries are approximate; their effective date is unspecified.</p><div class="control-area-buttons"></div><label class="control-formal-toggle"><input type="checkbox" id="${prefix}-formal-areas" data-nav><span>Formal self-administered boundaries</span></label><article class="control-selection" hidden></article><details class="control-relationships"><summary>Who controls what?</summary><p>Administrative states and regions are separate from armed control. Myanmar has several overlapping conflicts and ceasefire arrangements.</p><div class="control-actor-list"></div><p class="control-assessment">ISP-Myanmar estimated resistance control at about <strong>38%</strong> of land and <strong>87 towns</strong> during <strong>2025</strong>. This is a historical assessment, not a live map; the remainder was not necessarily all military-controlled. <a href="https://ispmyanmar.com/2026mp003/" target="_blank" rel="noopener">Assessment · 31 January 2026</a></p></details><a class="control-source" href="https://myanmar.iiss.org/methodology" target="_blank" rel="noopener">Control-reference sources</a></div>`;
 sidebar.querySelector('#'+prefix+'-layers-panel').prepend(panel);
 const toggle=panel.querySelector('#'+prefix+'-control-overlay'),formalToggle=panel.querySelector('#'+prefix+'-formal-areas'),content=panel.querySelector('.control-overview-content'),card=panel.querySelector('.control-selection'),buttons=panel.querySelector('.control-area-buttons');
 const ids={areas:country+'-control-areas',formal:country+'-control-formal',centres:country+'-control-centres'},layers=[country+'-control-fill',country+'-control-lines',country+'-control-formal-lines',country+'-control-points'];let active=false,quiz=false,selectedId=null;
 function addLink(parent,text,url){const a=document.createElement('a');a.textContent=text;a.href=url;a.target='_blank';a.rel='noopener';parent.append(a);}
 for(const r of facts.records){const b=document.createElement('button');b.type='button';b.className='quiet-button';b.textContent=r.en;b.dataset.controlPlace=r.id;b.onclick=()=>onSelect(r);buttons.append(b);}
 for(const actor of facts.actors){const d=document.createElement('details'),s=document.createElement('summary'),p=document.createElement('p');s.textContent=actor.name;p.textContent=actor.note;d.append(s,p);addLink(d,'Research source',actor.url);panel.querySelector('.control-actor-list').append(d);}
 function install(){if(map.getSource(ids.areas))return;
  map.addSource(ids.areas,{type:'geojson',data:territories,promoteId:'id',tolerance:.1,attribution:'IISS Myanmar Conflict Map · local research reference'});
  map.addSource(ids.formal,{type:'geojson',data:formal,tolerance:.1,attribution:'MIMU · formal self-administered boundaries'});
  map.addSource(ids.centres,{type:'geojson',data:{type:'FeatureCollection',features:facts.military.map(r=>({type:'Feature',properties:{id:r.id,name:r.name},geometry:{type:'Point',coordinates:r.center}}))}});
  map.addLayer({id:layers[0],type:'fill',source:ids.areas,metadata:{atlas:{thematic:true}},paint:{'fill-color':['get','color'],'fill-opacity':.48,'fill-antialias':false}});
  map.addLayer({id:layers[1],type:'line',source:ids.areas,paint:{'line-color':['get','color'],'line-width':['interpolate',['linear'],['zoom'],4,1,10,1.8],'line-opacity':.9}});
  map.addLayer({id:layers[2],type:'line',source:ids.formal,paint:{'line-color':'#725e32','line-width':1.2,'line-dasharray':[4,3]}});
  map.addLayer({id:layers[3],type:'circle',source:ids.centres,metadata:{atlas:{thematic:true}},paint:{'circle-radius':['interpolate',['linear'],['zoom'],4,4.5,9,7],'circle-color':'#b64a42','circle-stroke-color':'#fff','circle-stroke-width':1.5}});
 }
 function sync(state={}){if(state.active!==undefined)active=state.active;if(state.quiz!==undefined)quiz=state.quiz;const show=active&&!quiz&&toggle.checked;content.hidden=!toggle.checked;panel.hidden=quiz;if(active&&!quiz&&territories&&formal)install();if(!map.getSource(ids.areas))return;for(const id of layers)setLayerVisible(map,id,show&&(id!==layers[2]||formalToggle.checked));
  const firstLine=country+'-first-lines';if(map.getLayer(firstLine)){map.moveLayer(layers[0],firstLine);map.moveLayer(layers[1]);map.moveLayer(layers[2]);map.moveLayer(layers[3]);}
  if(map.getLayer(country+'-international'))map.moveLayer(country+'-international');
 }
 function clearSelection(){selectedId=null;card.hidden=true;card.replaceChildren();}
 async function select(id,{fit:shouldFit=true}={}){const r=byId.get(id);if(!r)return;toggle.checked=true;if(r.controlType==='formal')formalToggle.checked=true;selectedId=id;card.replaceChildren();const h=document.createElement('h3');h.textContent=r.en;card.append(h);
  const fields=r.controlType==='formal'?['Formal administrative boundary','This constitutional administrative area is not a current territorial-control polygon. In particular, Wa’s southern territory lies outside its formal self-administered division.']:r.controlType==='centre'?[r.date,r.note]:[r.actor,r.relationship,r.note,r.asOf,r.source];for(const text of fields){const p=document.createElement('p');p.textContent=text;card.append(p);}addLink(card,'Source',r.url||base+'control/sources.json');card.hidden=false;panel.querySelector('.control-relationships').open=false;sync();if(shouldFit&&r.bounds)await fit(r.bounds,r.controlType==='centre'?10:9);}
 function picked(point){if(!active||quiz||!toggle.checked)return;const candidates=[layers[3],...(formalToggle.checked?[layers[2]]:[]),layers[0]].filter(id=>map.getLayer(id));return map.queryRenderedFeatures(point,{layers:candidates}).map(f=>byId.get(f.properties.id)).find(Boolean);}
 toggle.onchange=()=>{if(!toggle.checked)clearSelection();sync();};formalToggle.onchange=()=>sync();
 return{records,picked,select,clearSelection,sync,async warm(){if(!territories||!formal)[territories,formal]=await Promise.all([loadCompressed(base+'control/territories.bin'),loadCompressed(base+'control/formal.bin')]);},get selectedId(){return selectedId;},leave(){active=false;clearSelection();sync();},dispose(){active=false;clearSelection();for(const id of layers)if(map.getLayer(id))map.removeLayer(id);for(const id of Object.values(ids))if(map.getSource(id))map.removeSource(id);territories=formal=undefined;}};
}
function featureBounds(g){const p=g.type==='Polygon'?g.coordinates:g.coordinates.flat(),b=[Infinity,Infinity,-Infinity,-Infinity];for(const ring of p)for(const [x,y]of ring){b[0]=Math.min(b[0],x);b[1]=Math.min(b[1],y);b[2]=Math.max(b[2],x);b[3]=Math.max(b[3],y);}return[[b[0],b[1]],[b[2],b[3]]];}
